// Пять самых частых слов в text.txt.
const fs = require('node:fs');

const words = fs.readFileSync('text.txt', 'utf8').toLowerCase().match(/[а-яёa-z]+/g) ?? [];
const counts = new Map();
for (const w of words) counts.set(w, (counts.get(w) ?? 0) + 1);
const top = [...counts.entries()].map(([w, c], i) => ({ w, c, i })).sort((a, b) => b.c - a.c || a.i - b.i).slice(0, 5);
for (const { w, c } of top) console.log(`${w}: ${c}`);
